    case 'masa':
      return { proteinPct: 25, fatPct: 25, carbsPct: 50 };
    default:
      return { proteinPct: 28, fatPct: 30, carbsPct: 42 };
  }
}

export function addMacros(a: Macros, b: Macros): Macros {
  return {
    kcal: a.kcal + b.kcal,
    protein: a.protein + b.protein,
    fat: a.fat + b.fat,
    carbs: a.carbs + b.carbs,
  };
