                  </span>
                </div>

                {entries.map((entry) => {
                  const recipe = derived.recipeMap.get(entry.recipeId);
                  const kcal = derived.recipeMacrosOf(entry.recipeId).kcal * entry.portions;
                  return (
                    <div className="entry" key={entry.id}>
                      <div className="entry-main">
                        <button
