                  </div>
                  {!check.ok ? (
                    <div className="tiny" style={{ color: 'var(--warn)' }}>
                      {check.reason}
                    </div>
                  ) : null}
                  <div className="chips">
                    {recipe.tags.slice(0, 3).map((tag) => (
                      <span className="tag" key={tag}>
                        {tag}
                      </span>
                    ))}
                  </div>
                </button>
              );
            })}
          </div>
        )}
      </div>

      {detailId ? (
        <RecipeDetail
          recipeId={detailId}
          onClose={() => setDetailId(null)}
          onEdit={(id) => {
            setDetailId(null);
            setEditing(id);
          }}
        />
      ) : null}

      {editing !== undefined ? (
        <RecipeEditor recipeId={editing} onClose={() => setEditing(undefined)} />
      ) : null}
    </div>
  );
}
