import { BASE_INGREDIENTS } from './src/data/ingredients';
import { BASE_RECIPES } from './src/data/recipes';
import { macroTargets, recipeMacros, kcalTarget } from './src/lib/nutrition';
import { generateWeek } from './src/lib/planner';
import { defaultPreferences, defaultProfile } from './src/lib/storage';
import { MEAL_ORDER, type Ingredient } from './src/types';

const ingredients = new Map<string, Ingredient>(BASE_INGREDIENTS.map((i) => [i.id, i]));
const profile = { ...defaultProfile(), age: 32, heightCm: 182, weightKg: 88 };
const preferences = defaultPreferences();
const target = kcalTarget(profile);
const goals = macroTargets(target.kcal, profile);

function seeded(seed: number) {
  let s = seed;
  return () => {
    s |= 0; s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

let kcalErr = 0, protRatio = 0, days = 0, worstProt = 9, bestProt = 0;
for (let seed = 1; seed <= 40; seed++) {
  const week = generateWeek({ recipes: BASE_RECIPES, ingredients, profile, preferences,
    dailyKcal: target.kcal, rng: seeded(seed) });
  for (const day of week) {
    let kcal = 0, prot = 0;
    for (const meal of MEAL_ORDER) for (const e of day[meal]) {
      const m = recipeMacros(BASE_RECIPES.find((r) => r.id === e.recipeId)!, ingredients);
      kcal += m.kcal * e.portions; prot += m.protein * e.portions;
    }
    kcalErr += Math.abs(kcal - target.kcal) / target.kcal;
    const r = prot / goals.protein;
    protRatio += r; worstProt = Math.min(worstProt, r); bestProt = Math.max(bestProt, r);
    days++;
  }
}
