import { macroTargets, recipeMacros, kcalTarget } from './src/lib/nutrition';
import { generateWeek } from './src/lib/planner';
import { defaultPreferences, defaultProfile } from './src/lib/storage';
import { MEAL_ORDER, type Ingredient } from './src/types';

const ingredients = new Map<string, Ingredient>(BASE_INGREDIENTS.map((i) => [i.id, i]));
const base = { ...defaultProfile(), age: 32, heightCm: 182, weightKg: 88 };
const preferences = defaultPreferences();
const target = kcalTarget(base);
const goals = macroTargets(target.kcal, base);

function seeded(seed: number) {
  let s = seed;
  return () => { s |= 0; s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}

// proteinPct = 0 wyłącza premię za białko (proteinFit zwraca wtedy 1) — to nasza próba kontrolna.
function run(label: string, proteinPct: number) {
  const profile = { ...base, proteinPct };
  let kcalErr = 0, prot = 0, days = 0, worst = 9;
  for (let seed = 1; seed <= 60; seed++) {
    for (const day of generateWeek({ recipes: BASE_RECIPES, ingredients, profile, preferences,
      dailyKcal: target.kcal, rng: seeded(seed) })) {
      let k = 0, p = 0;
      for (const meal of MEAL_ORDER) for (const e of day[meal]) {
        const m = recipeMacros(BASE_RECIPES.find((r) => r.id === e.recipeId)!, ingredients);
        k += m.kcal * e.portions; p += m.protein * e.portions;
      }
      kcalErr += Math.abs(k - target.kcal) / target.kcal;
      const r = p / goals.protein;
      prot += r; worst = Math.min(worst, r); days++;
    }
  }
  console.log(`${label.padEnd(22)} kcal ±${(kcalErr/days*100).toFixed(1)}%   białko ${(prot/days*100).toFixed(0)}% celu (najgorszy dzień ${(worst*100).toFixed(0)}%)`);
}

console.log(`Cel: ${target.kcal} kcal, ${goals.protein.toFixed(0)} g białka\n`);
run('bez premii', 0);
run('z premią za białko', base.proteinPct);
EOF
