p = 'src/components/ShoppingView.tsx'
s = open(p).read()

old = """  const copy = async () => {
    try {
      await navigator.clipboard.writeText(asText());
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // Bez uprawnień do schowka zostaje druk albo ręczne przepisanie.
      setCopied(false);
    }
  };"""

new = """  /**
   * `navigator.clipboard` istnieje tylko w bezpiecznym kontekście (HTTPS albo
   * localhost). Przy własnym serwerze po HTTP na adresie w sieci lokalnej go
   * nie ma, więc schodzimy do starego execCommand, a w ostateczności
   * pokazujemy tekst do ręcznego skopiowania.
   */
  const copy = async () => {
    const text = asText();

    if (navigator.clipboard?.writeText) {
      try {
        await navigator.clipboard.writeText(text);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
        return;
      } catch {
        // Odmowa uprawnień — próbujemy dalej.
      }
    }

    const area = document.createElement('textarea');
    area.value = text;
    area.setAttribute('readonly', '');
    area.style.position = 'fixed';
    area.style.opacity = '0';
    document.body.appendChild(area);
    area.select();

    let ok = false;
    try {
      ok = document.execCommand('copy');
    } catch {
      ok = false;
    }
    document.body.removeChild(area);

    if (ok) {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } else {
      setFallbackText(text);
    }
  };"""

assert old in s
s = s.replace(old, new)

s = s.replace(
  "  const [copied, setCopied] = useState(false);",
  "  const [copied, setCopied] = useState(false);\n  const [fallbackText, setFallbackText] = useState<string | null>(null);")

