cat > deploy/dieta.conf <<'EOF'
# Konfiguracja dla nginx zainstalowanego bezpośrednio na serwerze
# (bez Dockera). Skopiuj do /etc/nginx/sites-available/dieta
# i podlinkuj w /etc/nginx/sites-enabled/.
#
# Po uruchomieniu certbota ten plik zostanie przez niego uzupełniony
# o sekcję listen 443 ssl oraz przekierowanie z HTTP.

server {
    listen 80;
    listen [::]:80;

    # ZMIEŃ na swoją domenę (albo zostaw _ przy dostępie po samym IP).
    server_name dieta.example.com;

    root /var/www/dieta;
    index index.html;

    access_log /var/log/nginx/dieta.access.log;
    error_log  /var/log/nginx/dieta.error.log;

    gzip on;
    gzip_vary on;
    gzip_min_length 1024;
    gzip_types text/plain text/css application/javascript application/json image/svg+xml;

    location /assets/ {
        expires 1y;
        add_header Cache-Control "public, immutable";
        try_files $uri =404;
    }

    location = /index.html {
        add_header Cache-Control "no-cache, must-revalidate";
    }

    location / {
        try_files $uri $uri/ /index.html;
    }

    add_header X-Content-Type-Options "nosniff" always;
    add_header X-Frame-Options "SAMEORIGIN" always;
    add_header Referrer-Policy "same-origin" always;
}
EOF

cat > deploy/deploy.sh <<'EOF'
#!/usr/bin/env bash
#
# Buduje aplikację lokalnie i wysyła gotowe pliki na serwer.
# Nic nie kompiluje się po stronie serwera — leci tam sam katalog dist/.
#
# Użycie:
#   ./deploy/deploy.sh uzytkownik@serwer [katalog-docelowy]
#
# Przykład:
#   ./deploy/deploy.sh adam@192.168.1.10 /var/www/dieta

set -euo pipefail

TARGET="${1:-}"
REMOTE_DIR="${2:-/var/www/dieta}"

if [[ -z "$TARGET" ]]; then
    echo "Użycie: $0 uzytkownik@serwer [katalog-docelowy]" >&2
    exit 1
fi

cd "$(dirname "$0")/.."

echo "▸ Testy"
npm test

echo "▸ Budowanie"
npm run build

echo "▸ Wysyłka na ${TARGET}:${REMOTE_DIR}"
# --delete usuwa ze zdalnego katalogu pliki po starych wdrożeniach.
# Ukośnik po dist/ jest istotny: kopiujemy zawartość, a nie sam katalog.
rsync -avz --delete dist/ "${TARGET}:${REMOTE_DIR}/"

echo "▸ Gotowe. Sprawdź w przeglądarce."
EOF

